BEGIN;
CREATE FUNCTION public.lm_pick(j jsonb,keys text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$SELECT coalesce(jsonb_object_agg(k,v),'{}') FROM jsonb_each(j) e(k,v) WHERE k=ANY(string_to_array(keys,' '))$$;
CREATE VIEW public.lm_storefront AS SELECT id,revision,(SELECT jsonb_object_agg(k,v) FROM jsonb_each(data) e(k,v) WHERE k=ANY(string_to_array('businessName slogan logoUrl logoFont customLogoFontData bannerUrl faviconUrl productCategories accentColor themeDarkModeBg bgPattern shippingInfo',' '))) AS data FROM public.lm_store_private WHERE id='main';
CREATE VIEW public.lm_public_pricing AS SELECT id,revision,jsonb_build_object('baseEngravingPrice',data->'baseEngravingPrice','extraSidePrice',data->'extraSidePrice','logoSurcharge',data->'logoSurcharge') AS data FROM public.lm_pricing WHERE id='main';
CREATE FUNCTION public.lm_content_active(j jsonb) RETURNS boolean LANGUAGE sql STABLE AS $$SELECT coalesce(j->>'active','true')='true' AND (coalesce(j->>'startDate','')='' OR j->>'startDate'<=current_date::text) AND (coalesce(j->>'endDate','')='' OR j->>'endDate'>=current_date::text) AND (coalesce(j->>'validUntil','')='' OR j->>'validUntil'>=current_date::text)$$;
CREATE FUNCTION public.lm_content_item(j jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT public.lm_pick(j,'id image title subtitle link active order showOnHome description discount validUntil code name text rating avatar question answer category productId productName customMessage')$$;
CREATE FUNCTION public.lm_content_list(j jsonb) RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT coalesce(jsonb_agg(public.lm_content_item(x)),'[]') FROM jsonb_array_elements(j) x WHERE public.lm_content_active(x)$$;
CREATE VIEW public.lm_public_content AS SELECT id,revision,(SELECT jsonb_object_agg(k,public.lm_content_list(v)) FROM jsonb_each(data) e(k,v) WHERE k IN ('banners','promotions','testimonials','faqs','featuredProducts')) AS data FROM public.lm_content WHERE id='main';
CREATE FUNCTION public.lm_order_item(j jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT public.lm_pick(j,'id productId colorName quantity unitPrice totalPrice frontText frontText2 frontFontId frontFontId2 frontFontName frontDesignState frontDesignState2 frontLogos backText backText2 backFontId backFontId2 backFontName backDesignState backDesignState2 backLogos')$$;
CREATE FUNCTION public.lm_order_base(j jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$SELECT public.lm_pick(j,'id userId customerName customerPhone customerEmail total status paymentStatus paymentMethod deliveryMethod createdAt deliveryDate deliveryTime shippingProvider shippingTracking shippingAddress amountPaid couponUsed discountAmount pointsRedeemed mockupUrl')$$;
CREATE VIEW public.lm_my_orders AS SELECT id,revision,public.lm_order_base(data)||jsonb_build_object('items',(SELECT coalesce(jsonb_agg(public.lm_order_item(x)),'[]') FROM jsonb_array_elements(coalesce(data->'items','[]')) x)) AS data FROM public.lm_orders WHERE auth.uid() IS NOT NULL AND data->>'userId'=auth.uid()::text;
REVOKE ALL ON public.lm_storefront,public.lm_public_pricing,public.lm_public_content,public.lm_my_orders FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.lm_storefront,public.lm_public_pricing,public.lm_public_content TO anon,authenticated; GRANT SELECT ON public.lm_my_orders TO authenticated;
COMMIT;
